-- The guest's email for the venue's electronic receipt, kept only until the close (#186; D127,
-- "Martin 10-29"). Generated by drizzle-kit, then edited by hand: the trigger.
-- No row is updated or inserted here, so there is no backfill and no row-level-security step.
--   1. `payments.receipt_email`, and a check that it is a plausible address held only in a state up
--      to `checked` (the state the close is attempted from);
--   2. a trigger that erases it in the same update that leaves those states, whichever code makes
--      the update: the close, a cancel, a deadline, any final state.

ALTER TABLE "restro"."payments" ADD COLUMN "receipt_email" text;--> statement-breakpoint
ALTER TABLE "restro"."payments" ADD CONSTRAINT "payments_receipt_email" CHECK ("restro"."payments"."receipt_email" is null or (char_length("restro"."payments"."receipt_email") between 3 and 254 and "restro"."payments"."state" in ('requested', 'priced', 'awaiting_guest', 'held', 'queued', 'isolated', 'entered', 'checked')));--> statement-breakpoint

CREATE FUNCTION restro.payments_erase_receipt_email() RETURNS trigger
LANGUAGE plpgsql
SET search_path = pg_catalog
AS $$
BEGIN
  IF NEW.receipt_email IS NOT NULL
     AND NEW.state NOT IN ('requested', 'priced', 'awaiting_guest', 'held', 'queued', 'isolated', 'entered', 'checked') THEN
    NEW.receipt_email := NULL;
  END IF;
  RETURN NEW;
END
$$;--> statement-breakpoint
REVOKE ALL ON FUNCTION restro.payments_erase_receipt_email() FROM PUBLIC;--> statement-breakpoint
CREATE TRIGGER payments_erase_receipt_email BEFORE UPDATE ON "restro"."payments"
  FOR EACH ROW EXECUTE FUNCTION restro.payments_erase_receipt_email();
